		return false;
	}

	/* @Override */
	public bool paste(Transferable pasteData) {
		return false;
	}

	public bool pasteSpecial(Transferable pasteData, ClipboardType pasteType) {
		return false;
	}

	/* @Override */
	public void lostOwnership(Transferable transferable) {
		// no-op
	}

	public void setFontMetrics(FontMetrics metrics) {
		spaceCharWidthInPixels = metrics.charWidth(' ');
	}
}
